                       std::string description, helpUrl; bool container = false;
                       Policy policy = Policy::Confirm; };
struct AlgorithmSpec { AlgorithmInfo info; std::string longDescription;
                       std::vector<ArgSpec> args; std::string usageJson; };   // GDAL's --json-usage verbatim
using FieldValue = std::variant<std::monostate, bool, std::int64_t, double, std::string>;
enum class FieldType { Boolean, Integer64, Real, String, Date, DateTime };    // dates as ISO 8601 text
struct FieldDef { std::string name; FieldType type = FieldType::String; };
struct Feature { std::vector<VectorGeometry> parts;      // members of a multi-geometry; one for a simple one
                 std::vector<FieldValue> values; };      // parallel to FeatureTable::fields
struct FeatureTable { std::string name; GeometryKind kind = GeometryKind::Unknown; bool hasZ = false;
                      std::string crsWkt; std::vector<FieldDef> fields; std::vector<Feature> features; };
struct FeatureSet { std::vector<FeatureTable> tables; };
struct RasterGrid { RasterInfo info; std::string dataType = "Float64";
                    std::vector<std::vector<double>> bands;              // row major, top row first
                    std::vector<std::optional<double>> noData; };        // per band
struct DatasetPath { std::string path; std::vector<std::string> openOptions; std::string layer; };
using DatasetValue = std::variant<DatasetPath, RasterGrid, FeatureSet>;
using ArgValue = std::variant<Scalar, DatasetValue, std::vector<DatasetValue>>;
enum class OutputTo { Memory, File };
struct RunRequest {
    std::vector<std::string> path;                              // {"raster","hillshade"}, {"pipeline"}
    std::vector<std::pair<std::string, ArgValue>> values;       // long name, short name or alias
    std::vector<std::string> tokens;                            // GDAL-CLI tail, parsed after binding
    OutputTo outputTo = OutputTo::Memory;
    std::string outputPath, outputFormat;                       // File: "" format = from extension
    std::vector<std::string> creationOptions;                   // KEY=VALUE, File only
    bool overwrite = false;
    std::uint64_t maxMemoryCells = 64ull << 20;                 // larger raster outputs spill to a file
    std::string spillDirectory;
    std::vector<std::pair<std::string, std::string>> config;    // allow-listed thread-local options only
};
struct Diagnostic { bool failure = false; int code = 0; std::string message; };
struct RunOutputs { std::optional<RasterGrid> raster; std::optional<FeatureSet> features;
                    std::optional<std::string> file, text; std::optional<int> returnCode;
                    std::vector<Diagnostic> diagnostics; double seconds = 0.0; };
struct Versions { std::string gdal, release, proj, geos; int rasterDrivers = 0, vectorDrivers = 0, algorithms = 0; };

[[nodiscard]] const std::vector<AlgorithmInfo>& catalogue();       // from the root "gdal", cached, thread-safe
[[nodiscard]] core::Result<std::vector<std::string>> resolve(const std::vector<std::string>& words,
                                                             std::size_t& consumed); // longest match; aliases; case-insensitive
[[nodiscard]] core::Result<AlgorithmSpec> describe(const std::vector<std::string>& path);
[[nodiscard]] std::vector<std::string> suggest(const std::vector<std::string>& path, const std::string& arg,
                                               const std::string& prefix);           // GetAutoCompleteChoices
[[nodiscard]] core::Status validate(const RunRequest&);             // binds and ValidateArguments(); runs nothing
[[nodiscard]] core::Result<RunOutputs> run(const RunRequest&, const std::stop_token& stop = {},
                                           const std::function<void(double)>& progress = {});
[[nodiscard]] Versions versions();
}
```

- `resolve` on a container fails with `InvalidArgument` and lists the container's children.
- `run` fails with:
  - `InvalidState` "cancelled";
  - `InvalidArgument` (validation);
  - `FileImportFailure` / `FileExportFailure`;
  - `CommandRejected`, carrying GDAL's first failure message.

